  attr_reader :amount, :unit

  def initialize(amount, unit)
    @amount = amount
    @unit = unit
  end

  def <=>(other)
    ensure_same_unit!(other)
    @amount <=> other.amount
  end

  def ==(other)
    other.is_a?(Weight) && @amount == other.amount && @unit == other.unit
  end

  def <(other)
    ensure_same_unit!(other)
    @amount < other.amount
  end

  def <=(other)
    ensure_same_unit!(other)
    @amount <= other.amount
  end

  def >(other)
    ensure_same_unit!(other)
    @amount > other.amount
  end

  def >=(other)
    ensure_same_unit!(other)
    @amount >= other.amount
  end

  def clamp(lower, upper)
    ensure_same_unit!(lower)
    ensure_same_unit!(upper)
    if @amount < lower.amount
      lower
    elsif @amount > upper.amount
      upper
    else
      self
    end
  end

  def between?(min, max)
    ensure_same_unit!(min)
    ensure_same_unit!(max)
    @amount >= min.amount && @amount <= max.amount
  end

  private

  def ensure_same_unit!(other)
    raise ArgumentError, "Cannot compare weights with different units" unless other.is_a?(Weight) && @unit == other.unit
  end
end
